function getWordMeaningAndTafsir(word, ayahEntry, surahName) {
	if (ayahEntry.meanings && ayahEntry.meanings[word]) return {
		wordMeaning: ayahEntry.meanings[word],
		ayahTafsir: ayahEntry.tafsir,
		tafsirSource: "التفسير الميسر (مجمع الملك فهد) & السراج في غريب القرآن",
		tajweedNote: detectQuickWordTajweedHint(word)
	};
	const normTarget = normalizeArabicWordForLookup(word);
	if (ayahEntry.meanings) for (const [k, v] of Object.entries(ayahEntry.meanings)) {
		const normK = normalizeArabicWordForLookup(k);
		if (normK && (normK === normTarget || normK.includes(normTarget) || normTarget.includes(normK))) return {
			wordMeaning: v,
			ayahTafsir: ayahEntry.tafsir,
			tafsirSource: "التفسير الميسر (مجمع الملك فهد) & السراج في غريب القرآن",
			tajweedNote: detectQuickWordTajweedHint(word)
		};
	}
	const strippedPrefix = normTarget.replace(/^[وفبل]/, "");
	const dictMatch = COMMON_QURAN_WORD_MEANINGS[normTarget] || COMMON_QURAN_WORD_MEANINGS[strippedPrefix];
	if (dictMatch) return {
		wordMeaning: dictMatch,
		ayahTafsir: ayahEntry.tafsir,
		tafsirSource: "التفسير الميسر (مجمع الملك فهد) & السراج في غريب القرآن",
		tajweedNote: detectQuickWordTajweedHint(word)
	};
	return {
		wordMeaning: `لفظ قرآني كريم في الآية (${ayahEntry.ayah}) من سورة ${surahName}؛ معناه في سياق الآية: ${ayahEntry.tafsir}`,
		ayahTafsir: ayahEntry.tafsir,
		tafsirSource: "التفسير الميسر — مجمع الملك فهد لطباعة المصحف الشريف",
		tajweedNote: detectQuickWordTajweedHint(word)
	};
}
function detectQuickWordTajweedHint(word) {
	const hints = [];
	if (/[آٰٓ]|(ا|و|ي)ء/.test(word)) hints.push("مد (طبيعي / فرعي يراعى فيه زمن المد)");
	if (/(نّ|مّ|ّ[نم]|[نم]ّ|[ًٌٍ])/.test(word)) hints.push("غنة / حكم نون أو ميم مشددة أو تنوين (حركتان)");
	if (/[قطبجد]/.test(word)) hints.push("يحتوي على حرف من حروف القلقلة (قُطْبُ جَدّ) إن سُكّن");
	if (/[خصضغطقظ]/.test(word)) hints.push("يحتوي على حرف استعلاء مفخم دائماً (خُصّ ضَغْطٍ قِظ)");
	return hints.length > 0 ? hints.join(" • ") : "تراعى إتمام الحركات وتحقيق مخارج الحروف والترقيق";
}
