function makeRemedy(item) {
	return {
		...item,
		letter: item.targetLetters,
		defectTitle: item.title,
		commonMistake: item.commonError,
		practicalExercise: item.practicalRemedy,
		quranicDrillWords: item.drillWords
	};
}
