function convertAcademyTimeToStudentZone(academyTimeHHmm, offsetFromCairoHours) {
	const [hStr, mStr] = (academyTimeHHmm || "17:00").split(":");
	const baseH = Number(hStr) || 17;
	const baseM = Number(mStr) || 0;
	let shiftedH = baseH + offsetFromCairoHours;
	let dayShiftLabel = "نفس اليوم";
	if (shiftedH >= 24) {
		shiftedH -= 24;
		dayShiftLabel = "اليوم التالي (+1)";
	} else if (shiftedH < 0) {
		shiftedH += 24;
		dayShiftLabel = "اليوم السابق (-1)";
	}
	const period = shiftedH >= 12 ? "م" : "ص";
	const h12 = shiftedH % 12 === 0 ? 12 : shiftedH % 12;
	const padM = String(baseM).padStart(2, "0");
	return {
		studentTime24: `${String(shiftedH).padStart(2, "0")}:${padM}`,
		studentTimeFormatted: `${h12}:${padM} ${period}`,
		dayShiftLabel
	};
}
function predictStudentKhatmah(student, sessions) {
	const stSessions = sessions.filter((s) => s.studentId === student.id && s.status === "حضر");
	const totalAyatRecited = stSessions.reduce((acc, ses) => {
		if (ses.actualRecitation?.enabled) return acc + Math.max(1, ses.actualRecitation.toAyah - ses.actualRecitation.fromAyah + 1);
		if (ses.newMemorization?.enabled) return acc + Math.max(1, ses.newMemorization.toAyah - ses.newMemorization.fromAyah + 1);
		return acc + 10;
	}, 0);
	const avgAyatPerSession = stSessions.length > 0 ? Math.max(5, Math.round(totalAyatRecited / stSessions.length)) : student.plan === "مكثفة" ? 20 : 12;
	const weeklySessionsCount = Math.max(1, student.scheduleDays.length || 3);
	const completedJuzCount = student.memorizedJuz.length;
	const remainingJuzCount = Math.max(1, 30 - completedJuzCount);
	const sessionsPerJuz = Math.max(4, Math.ceil(200 / avgAyatPerSession));
	const daysToFinishCurrentJuz = Math.max(7, Math.round(sessionsPerJuz * .65 / weeklySessionsCount * 7));
	const totalRemainingSessions = remainingJuzCount * sessionsPerJuz;
	const totalRemainingWeeks = Math.ceil(totalRemainingSessions / weeklySessionsCount);
	const totalRemainingMonths = Math.max(1, Math.round(totalRemainingWeeks / 4.3));
	const currentJuzDate = /* @__PURE__ */ new Date();
	currentJuzDate.setDate(currentJuzDate.getDate() + daysToFinishCurrentJuz);
	const fullKhatmahDate = /* @__PURE__ */ new Date();
	fullKhatmahDate.setDate(fullKhatmahDate.getDate() + totalRemainingWeeks * 7);
	return {
		avgAyatPerSession,
		weeklySessionsCount,
		completedJuzCount,
		remainingJuzCount,
		daysToFinishCurrentJuz,
		expectedCurrentJuzDate: currentJuzDate.toISOString().slice(0, 10),
		expectedFullKhatmahDate: fullKhatmahDate.toISOString().slice(0, 10),
		totalRemainingMonths,
		totalRemainingSessions
	};
}
