function evaluatePedagogicalScreening(answers, teacherObservationNote) {
	const styleScores = {
		سمعي: 0,
		بصري: 0,
		"حركي/تفاعلي": 0
	};
	const challengeScores = {
		pronunciation_makharij: 0,
		attention_hyperactivity: 0,
		slow_memorization: 0,
		weak_reading_foundation: 0,
		balanced_typical: 0
	};
	const hasExplicitAnswers = Object.keys(answers).length > 0;
	for (const q of PEDAGOGICAL_SCREENING_QUESTIONS) {
		const pickedId = answers[q.id];
		const pickedOpt = hasExplicitAnswers ? q.options.find((o) => o.id === pickedId) : q.options[0];
		if (!pickedOpt) continue;
		if (pickedOpt.learningStyleWeight) Object.keys(pickedOpt.learningStyleWeight).forEach((st) => {
			styleScores[st] += pickedOpt.learningStyleWeight?.[st] || 0;
		});
		if (pickedOpt.challengeWeight) Object.keys(pickedOpt.challengeWeight).forEach((ch) => {
			challengeScores[ch] += pickedOpt.challengeWeight?.[ch] || 0;
		});
	}
	const learningStyle = Object.keys(styleScores).sort((a, b) => styleScores[b] - styleScores[a])[0] || "سمعي";
	const sortedSpecific = [
		"weak_reading_foundation",
		"pronunciation_makharij",
		"attention_hyperactivity",
		"slow_memorization"
	].sort((a, b) => challengeScores[b] - challengeScores[a]);
	const topChallenge = sortedSpecific[0];
	const primaryChallengeKey = challengeScores[topChallenge] >= 2 ? topChallenge : "balanced_typical";
	const secondaryChallenges = sortedSpecific.slice(1).filter((k) => challengeScores[k] >= 2).map((k) => CHALLENGE_METADATA[k].shortBadge);
	const meta = CHALLENGE_METADATA[primaryChallengeKey];
	let suggestedTrack = meta.defaultTrack;
	if (primaryChallengeKey === "weak_reading_foundation") suggestedTrack = "تأسيس قرائي";
	else if (primaryChallengeKey === "attention_hyperactivity" || primaryChallengeKey === "slow_memorization") suggestedTrack = "تحفيظ بجرعات صغيرة";
	else if (learningStyle === "سمعي") suggestedTrack = "تلقين سمعي";
	return {
		assessedAt: (/* @__PURE__ */ new Date()).toISOString().slice(0, 10),
		learningStyle,
		primaryChallengeKey,
		primaryChallengeLabel: meta.label,
		secondaryChallenges,
		suggestedTrack,
		teacherActionSummary: meta.teacherActionSummary,
		recommendedSessionSliceMinutes: meta.sliceMinutes,
		recommendedDailyListeningCount: meta.dailyListening,
		rawAnswers: answers,
		teacherObservationNote: teacherObservationNote?.trim() || void 0
	};
}
