function getRepeatedErrorsPedagogicalTips(errors) {
	const grouped = {};
	for (const err of errors || []) {
		const key = err.type || "حفظ";
		if (!grouped[key]) grouped[key] = {
			count: 0,
			words: /* @__PURE__ */ new Set()
		};
		const increment = err.repeatCount && err.repeatCount > 1 ? err.repeatCount : 1;
		grouped[key].count += increment;
		if (err.word) grouped[key].words.add(err.word);
	}
	return Object.entries(grouped).filter(([, data]) => data.count >= 1).sort((a, b) => b[1].count - a[1].count).map(([errorType, data]) => ({
		errorType,
		count: data.count,
		sampleWords: Array.from(data.words).slice(0, 3),
		tip: ERROR_PEDAGOGICAL_COACHING_MAP[errorType] || ERROR_PEDAGOGICAL_COACHING_MAP["حفظ"]
	}));
}
