function detectWordAutoTajweedCategory(word, hasMutashabihat) {
	if (hasMutashabihat) return {
		category: "mutashabihat",
		color: "#7c3aed",
		ruleLabel: "موضع متشابهات قرآنية"
	};
	if (/[آٰٓ]|(ا|و|ي)ء/.test(word)) return {
		category: "madd",
		color: "#ea580c",
		ruleLabel: "حكم مد (متصل / منفصل / بدل / طبيعي)"
	};
	if (/(نّ|مّ|ّ[نم]|[نم]ّ|[ًٌٍ])/.test(word)) return {
		category: "ghunnah",
		color: "#16a34a",
		ruleLabel: "حكم غنة / نون وميم مشددة أو تنوين"
	};
	if (/[قطبجدخصضغظ]/.test(word)) return {
		category: "qalqalah",
		color: "#2563eb",
		ruleLabel: "قلقلة (قطب جد) أو حرف تفخيم واستعلاء"
	};
	return {
		category: null,
		color: "",
		ruleLabel: ""
	};
}
