var STUDENT_IDB_DB_NAME = "wlq_student_audio_idb_v1";
var STUDENT_IDB_STORE_NAME = "student_audio_blobs";
function openStudentRecitationsIDB() {
	return new Promise((resolve) => {
		try {
			if (typeof indexedDB === "undefined") {
				resolve(null);
				return;
			}
			const req = indexedDB.open(STUDENT_IDB_DB_NAME, 1);
			req.onupgradeneeded = () => {
				const db = req.result;
				if (!db.objectStoreNames.contains(STUDENT_IDB_STORE_NAME)) db.createObjectStore(STUDENT_IDB_STORE_NAME, { keyPath: "id" }).createIndex("by_studentId", "studentId", { unique: false });
			};
			req.onsuccess = () => resolve(req.result);
			req.onerror = () => resolve(null);
		} catch {
			resolve(null);
		}
	});
}
async function putBlobInStudentIndexedDB(entry) {
	const db = await openStudentRecitationsIDB();
	if (!db) return;
	await new Promise((resolve) => {
		try {
			const tx = db.transaction(STUDENT_IDB_STORE_NAME, "readwrite");
			tx.objectStore(STUDENT_IDB_STORE_NAME).put(entry);
			tx.oncomplete = () => resolve();
			tx.onerror = () => resolve();
		} catch {
			resolve();
		}
	});
}
async function getBlobsFromStudentIndexedDB(targetStudentId) {
	const db = await openStudentRecitationsIDB();
	if (!db) return [];
	return new Promise((resolve) => {
		try {
			const req = db.transaction(STUDENT_IDB_STORE_NAME, "readonly").objectStore(STUDENT_IDB_STORE_NAME).index("by_studentId").getAll(IDBKeyRange.only(targetStudentId));
			req.onsuccess = () => resolve((req.result || []).sort((a, b) => b.createdAt.localeCompare(a.createdAt)));
			req.onerror = () => resolve([]);
		} catch {
			resolve([]);
		}
	});
}
async function deleteBlobFromStudentIndexedDB(recordId) {
	const db = await openStudentRecitationsIDB();
	if (!db) return;
	await new Promise((resolve) => {
		try {
			const tx = db.transaction(STUDENT_IDB_STORE_NAME, "readwrite");
			tx.objectStore(STUDENT_IDB_STORE_NAME).delete(recordId);
			tx.oncomplete = () => resolve();
			tx.onerror = () => resolve();
		} catch {
			resolve();
		}
	});
}
