/**
* Packages an array of JPEG DataURLs (rendered A4 canvases) into a multi-page standard PDF 1.4 binary Blob.
*/
function buildPdfFromJpegPages(pages) {
	const encoder = new TextEncoder();
	const chunks = [];
	let offset = 0;
	const pushStr = (str) => {
		const bytes = encoder.encode(str);
		chunks.push(bytes);
		offset += bytes.length;
	};
	const pushBytes = (bytes) => {
		chunks.push(bytes);
		offset += bytes.length;
	};
	const xrefOffsets = [0];
	pushStr("%PDF-1.4\n%ÿÿÿÿ\n");
	xrefOffsets[1] = offset;
	pushStr("1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n");
	const pageObjIds = pages.map((_, idx) => 3 + idx * 3);
	xrefOffsets[2] = offset;
	pushStr(`2 0 obj\n<< /Type /Pages /Kids [${pageObjIds.map((id) => `${id} 0 R`).join(" ")}] /Count ${pages.length} >>\nendobj\n`);
	pages.forEach((page, idx) => {
		const pageObjId = 3 + idx * 3;
		const contentObjId = pageObjId + 1;
		const imageObjId = pageObjId + 2;
		const base64Data = page.dataUrl.split(",")[1] || "";
		const binaryStr = atob(base64Data);
		const imgBytes = new Uint8Array(binaryStr.length);
		for (let i = 0; i < binaryStr.length; i++) imgBytes[i] = binaryStr.charCodeAt(i);
		xrefOffsets[pageObjId] = offset;
		pushStr(`${pageObjId} 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${page.widthPt} ${page.heightPt}] /Resources << /XObject << /Im0 ${imageObjId} 0 R >> >> /Contents ${contentObjId} 0 R >>\nendobj\n`);
		const contentStream = `q\n${page.widthPt} 0 0 ${page.heightPt} 0 0 cm\n/Im0 Do\nQ\n`;
		xrefOffsets[contentObjId] = offset;
		pushStr(`${contentObjId} 0 obj\n<< /Length ${contentStream.length} >>\nstream\n${contentStream}endstream\nendobj\n`);
		xrefOffsets[imageObjId] = offset;
		pushStr(`${imageObjId} 0 obj\n<< /Type /XObject /Subtype /Image /Width ${page.pixelWidth} /Height ${page.pixelHeight} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${imgBytes.length} >>\nstream\n`);
		pushBytes(imgBytes);
		pushStr("\nendstream\nendobj\n");
	});
	const xrefStart = offset;
	const totalObjects = xrefOffsets.length;
	pushStr(`xref\n0 ${totalObjects}\n0000000000 65535 f \n`);
	for (let i = 1; i < totalObjects; i++) pushStr(`${String(xrefOffsets[i]).padStart(10, "0")} 00000 n \n`);
	pushStr(`trailer\n<< /Size ${totalObjects} /Root 1 0 R >>\nstartxref\n${xrefStart}\n%%EOF`);
	return new Blob(chunks, { type: "application/pdf" });
}
